def main():
    nb = nw = 0
    for f in sorted(os.listdir(os.path.join(ROOT, 'guide'))):
        path = os.path.join(ROOT, 'guide', f); g = json.load(open(path))
        for s in g['sections']:
            if not s.get('subtopic') and g['topic'] in B: s['bridge'] = B[g['topic']]; nb += 1
            if s.get('subtopic') in WORK: s['work'] = WORK[s['subtopic']]; nw += 1
        json.dump(g, open(path, 'w'), indent=1, ensure_ascii=False); open(path, 'a').write('\n')
    print('topic bridges:', nb, 'lesson notes from practice:', nw)
if __name__ == '__main__': main()
